package com.witchersbestiary.test;
import com.witchersbestiary.workshop.*;
import net.fabricmc.fabric.api.gametest.v1.FabricGameTest;
import net.minecraft.test.*;import net.minecraft.item.*;import net.minecraft.util.math.BlockPos;
public final class AlchemyTableTests implements FabricGameTest {
 private WorkshopInventory table(TestContext c){var pos=c.getAbsolutePos(new BlockPos(1,2,1));c.getWorld().setBlockState(pos,ModWorkshop.BLOCKS.get(WorkshopKind.ALCHEMY_WORKBENCH).getDefaultState());return (WorkshopInventory)c.getWorld().getBlockEntity(pos);}
 @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,batchId="alchemy-all")
 public void everyActualRecipeConsumesOnceAndKeepsExistingBlock(TestContext c){var t=table(c);var p=c.createMockCreativeServerPlayerInWorld();p.refreshPositionAndAngles(t.getPos().getX()+.5,t.getPos().getY(),t.getPos().getZ()+2,0,0);var recipes=AlchemyRecipes.catalog(c.getWorld());c.assertTrue(recipes.size()>=17,"Real registered consumables and three refinements");for(int n=0;n<recipes.size();n++){p.getInventory().clear();t.clear();var recipe=recipes.get(n);for(var ingredient:recipe.value().getIngredients())if(!ingredient.isEmpty()){var stack=ingredient.getMatchingStacks()[0].copyWithCount(1);p.getInventory().insertStack(stack);}c.assertTrue(AlchemyRecipes.craft(t,p,n),"Craft actual recipe "+recipe.id());var result=recipe.value().getResult(c.getWorld().getRegistryManager());c.assertTrue(ItemStack.areItemsAndComponentsEqual(t.getStack(3),result)&&t.getStack(3).getCount()==result.getCount(),"Exact result "+recipe.id());c.assertTrue(!AlchemyRecipes.craft(t,p,n),"Replay cannot create output without inputs "+recipe.id());}p.discard();c.complete();}
 @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,batchId="alchemy-safety")
 public void fullOutputDistanceAndSharedTableAreAtomic(TestContext c){var t=table(c);var a=c.createMockCreativeServerPlayerInWorld();var b=c.createMockCreativeServerPlayerInWorld();for(var p:java.util.List.of(a,b)){p.refreshPositionAndAngles(t.getPos().getX()+.5,t.getPos().getY(),t.getPos().getZ()+2,0,0);p.getInventory().clear();}var recipes=AlchemyRecipes.catalog(c.getWorld());int id=0;var entry=recipes.get(id);for(var ingredient:entry.value().getIngredients())if(!ingredient.isEmpty())a.getInventory().insertStack(ingredient.getMatchingStacks()[0].copyWithCount(1));t.setStack(3,new ItemStack(Items.STONE,64));var before=a.getInventory().writeNbt(new net.minecraft.nbt.NbtList()).toString();c.assertTrue(!AlchemyRecipes.craft(t,a,id)&&before.equals(a.getInventory().writeNbt(new net.minecraft.nbt.NbtList()).toString()),"Blocked output never consumes");t.setStack(3,ItemStack.EMPTY);c.assertTrue(AlchemyRecipes.craft(t,a,id)&&!AlchemyRecipes.craft(t,b,id),"Second player cannot reuse first player's inputs");var saved=t.createNbt(c.getWorld().getRegistryManager());var restored=new WorkshopInventory(t.getPos(),t.getCachedState());restored.read(saved,c.getWorld().getRegistryManager());c.assertTrue(ItemStack.areEqual(restored.getStack(3),t.getStack(3)),"Existing four-slot serialization retained");a.refreshPositionAndAngles(t.getPos().getX()+100,t.getPos().getY(),t.getPos().getZ(),0,0);c.assertTrue(!AlchemyRecipes.craft(t,a,id)&&!AlchemyRecipes.craft(t,b,-1),"Distance and forged selection rejected");a.discard();b.discard();c.complete();}
}
